/*
 * Match Games service worker: offline cache with manual-only updates.
 *
 * DO NOT EDIT THIS FILE after the app has been released.
 *
 * Browsers re-download sw.js in the background and install it automatically
 * if a single byte differs. Keeping this file frozen means that background
 * check never changes anything, so the app only updates when the user taps
 * "Check for updates" in Settings → App. App versions live in version.json,
 * which the build writes (see vite.config.ts). The build fails if this file's
 * hash changes, to stop accidental edits.
 *
 * Flow:
 *  - First install: download every file in version.json into a cache named
 *    after that version, and remember it as the current version.
 *  - Every request in scope is answered from the current version's cache;
 *    page navigations get its index.html (single-page app routing).
 *  - "check-update" message: fetch version.json, and if it names a different
 *    version, download that version completely, switch to it, and delete the
 *    old one. Any failure leaves the current version untouched.
 */

const SCOPE = self.registration.scope
const VERSION_PREFIX = 'match-app-'
const META_CACHE = 'match-meta'
const POINTER_URL = new URL('__current-version', SCOPE).href
const INDEX_URL = new URL('index.html', SCOPE).href

let updateInProgress = null

async function getCurrent() {
  const meta = await caches.open(META_CACHE)
  const res = await meta.match(POINTER_URL)
  return res ? res.json() : null
}

async function setCurrent(info) {
  const meta = await caches.open(META_CACHE)
  await meta.put(
    POINTER_URL,
    new Response(JSON.stringify(info), {
      headers: { 'content-type': 'application/json' },
    }),
  )
}

async function fetchVersionManifest() {
  const res = await fetch(new URL('version.json', SCOPE).href, {
    cache: 'no-store',
  })
  if (!res.ok) throw new Error(`Update server returned ${res.status}`)
  const manifest = await res.json()
  if (typeof manifest.version !== 'string' || !Array.isArray(manifest.files)) {
    throw new Error('Update information is malformed')
  }
  return manifest
}

// Safari refuses to serve redirected responses to navigations, so store a
// clean copy of anything that came through a redirect.
async function storable(res) {
  if (!res.redirected) return res
  return new Response(await res.blob(), {
    status: res.status,
    statusText: res.statusText,
    headers: res.headers,
  })
}

async function installVersion(manifest) {
  const name = VERSION_PREFIX + manifest.version
  await caches.delete(name) // discard leftovers from an interrupted attempt
  const cache = await caches.open(name)
  try {
    await Promise.all(
      manifest.files.map(async (path) => {
        const url = new URL(path, SCOPE).href
        const res = await fetch(url, { cache: 'no-store' })
        if (!res.ok) throw new Error(`Couldn't download ${path} (${res.status})`)
        await cache.put(url, await storable(res))
      }),
    )
  } catch (err) {
    await caches.delete(name)
    throw err
  }
  // Switch only once every file is safely stored.
  const info = { version: manifest.version, built: manifest.built }
  await setCurrent(info)
  for (const key of await caches.keys()) {
    if (key.startsWith(VERSION_PREFIX) && key !== name) await caches.delete(key)
  }
  return info
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      if (!(await getCurrent())) await installVersion(await fetchVersionManifest())
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim())
})

async function respond(request) {
  const current = await getCurrent()
  if (!current) return fetch(request)
  const cache = await caches.open(VERSION_PREFIX + current.version)
  if (request.mode === 'navigate') {
    return (await cache.match(INDEX_URL)) ?? fetch(request)
  }
  return (await cache.match(request.url)) ?? fetch(request)
}

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET' || !request.url.startsWith(SCOPE)) return
  event.respondWith(respond(request))
})

self.addEventListener('message', (event) => {
  const port = event.ports && event.ports[0]
  const type = event.data && event.data.type
  if (!port) return
  const reply = (body) => port.postMessage(body)

  event.waitUntil(
    (async () => {
      try {
        if (type === 'status') {
          reply({ ok: true, updated: false, current: await getCurrent() })
        } else if (type === 'check-update') {
          if (!updateInProgress) {
            updateInProgress = (async () => {
              const manifest = await fetchVersionManifest()
              const current = await getCurrent()
              if (current && current.version === manifest.version) {
                return { ok: true, updated: false, current }
              }
              return { ok: true, updated: true, current: await installVersion(manifest) }
            })().finally(() => {
              updateInProgress = null
            })
          }
          reply(await updateInProgress)
        } else {
          reply({ ok: false, error: `Unknown request: ${type}` })
        }
      } catch (err) {
        reply({ ok: false, error: (err && err.message) || String(err) })
      }
    })(),
  )
})
